import{_ as t,a0 as s,w as c,s as r,ao as n,I as d,x as i,a1 as o,A as a}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const T=JSON.parse('{"title":"使用 Vi/Vim 編輯器：基礎篇 | LCTT x X-CMD","titleTemplate":false,"description":"使用 Vi/Vim 編輯器：基礎篇 | LCTT (201802) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"使用 Vi/Vim 編輯器：基礎篇 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"使用 Vi/Vim 編輯器：基礎篇 | LCTT (201802) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201802/20170511 Working with VI editor - The Basics","title":"使用 Vi/Vim 編輯器：基礎篇","tag":"201802","desc":""},"relativePath":"201802/20170511 Working with VI editor - The Basics.md","filePath":"[post].md"}'),p={name:"201802/20170511 Working with VI editor - The Basics.md"};function h(m,e,V,b,f,u){const l=s("Link");return c(),r("div",null,[e[8]||(e[8]=n('<h1 id="使用-vi-vim-編輯器-基礎篇" tabindex="-1">使用 Vi/Vim 編輯器：基礎篇 <a class="header-anchor" href="#使用-vi-vim-編輯器-基礎篇" aria-label="Permalink to “使用 Vi/Vim 編輯器：基礎篇”">​</a></h1><p>VI 編輯器是一個基於命令列的、功能強大的文本編輯器，最早為 Unix 系統開發，後來也被移植到許多的 Unix 和 Linux 發行版上。</p><p>在 Linux 上還存在着另一個 VI 編輯器的高階版本 —— VIM（也被稱作 VI IMproved）。VIM 只是在 VI 已經很強的功能上添加了更多的功能，這些功能有：</p><ul><li>支持更多 Linux 發行版，</li><li>支持多種編程語言，包括 python、c++、perl 等語言的代碼塊摺疊，語法高亮，</li><li>支持通過多種網絡協議，包括 http、ssh 等編輯文件，</li><li>支持編輯壓縮歸檔中的文件，</li><li>支持分屏同時編輯多個文件。</li></ul><p>接下來我們會討論 VI/VIM 的命令以及選項。本文出於教學的目的，我們使用 VI 來舉例，但所有的命令都可以被用於 VIM。首先我們先介紹 VI 編輯器的兩種模式。</p><h3 id="命令模式" tabindex="-1">命令模式 <a class="header-anchor" href="#命令模式" aria-label="Permalink to “命令模式”">​</a></h3><p>命令模式下，我們可以執行保存文件、在 VI 內運行命令、複製/剪切/粘貼操作，以及查找/替換等任務。當我們處於插入模式時，我們可以按下 <code>Escape</code>（<code>Esc</code>）鍵返回命令模式</p><h3 id="插入模式" tabindex="-1">插入模式 <a class="header-anchor" href="#插入模式" aria-label="Permalink to “插入模式”">​</a></h3><p>在插入模式下，我們可以鍵入文件內容。在命令模式下按下 <code>i</code> 進入插入模式。</p><h3 id="創建文件" tabindex="-1">創建文件 <a class="header-anchor" href="#創建文件" aria-label="Permalink to “創建文件”">​</a></h3><p>我們可以通過下述命令建立一個文件（LCTT 譯註：如果該文件存在，則編輯已有文件）：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ vi filename</span></span></code></pre></div><p>一旦該文件被創建或者打開，我們首先進入命令模式，我們需要進入輸入模式以在文件中輸入內容。我們通過前文已經大致上瞭解這兩種模式。</p><h3 id="退出-vi" tabindex="-1">退出 Vi <a class="header-anchor" href="#退出-vi" aria-label="Permalink to “退出 Vi”">​</a></h3><p>如果是想從插入模式中退出，我們首先需要按下 <code>Esc</code> 鍵進入命令模式。接下來我們可以根據不同的需要分別使用兩種命令退出 Vi。</p><ol><li>不保存退出 - 在命令模式中輸入 <code>:q!</code></li><li>保存並退出 - 在命令模式中輸入 <code>:wq</code></li></ol><h3 id="移動光標" tabindex="-1">移動光標 <a class="header-anchor" href="#移動光標" aria-label="Permalink to “移動光標”">​</a></h3><p>下面我們來討論下那些在命令模式中移動光標的命令和選項：</p><ol><li><p><code>k</code> 將光標上移一行</p></li><li><p><code>j</code> 將光標下移一行</p></li><li><p><code>h</code> 將光標左移一個字母</p></li><li><p><code>l</code> 將光標右移一個字母</p><p>注意：如果你想通過一個命令上移或下移多行，或者左移、右移多個字母，你可以使用 <code>4k</code> 或者 <code>5l</code>，這兩條命令會分別上移 4 行或者右移 5 個字母。</p></li><li><p><code>0</code> 將光標移動到該行行首</p></li><li><p><code>$</code> 將光標移動到該行行尾</p></li><li><p><code>nG</code> 將光標移動到第 n 行</p></li><li><p><code>G</code> 將光標移動到文件的最後一行</p></li><li><p><code>{</code> 將光標移動到上一段</p></li><li><p><code>}</code> 將光標移動到下一段</p></li></ol><p>除此之外還有一些命令可以用於控制光標的移動，但上述列出的這些命令應該就能應付日常工作所需。</p><h3 id="編輯文本" tabindex="-1">編輯文本 <a class="header-anchor" href="#編輯文本" aria-label="Permalink to “編輯文本”">​</a></h3><p>這部分會列出一些用於命令模式的命令，可以進入插入模式來編輯當前文件</p><ol><li><code>i</code> 在當前光標位置之前插入內容</li><li><code>I</code> 在光標所在行的行首插入內容</li><li><code>a</code> 在當前光標位置之後插入內容</li><li><code>A</code> 在光標所在行的行尾插入內容</li><li><code>o</code> 在當前光標所在行之後添加一行</li><li><code>O</code> 在當前光標所在行之前添加一行</li></ol><h3 id="刪除文本" tabindex="-1">刪除文本 <a class="header-anchor" href="#刪除文本" aria-label="Permalink to “刪除文本”">​</a></h3><p>以下的這些命令都只能在命令模式下使用，所以首先需要按下 <code>Esc</code> 進入命令模式，如果你正處於插入模式：</p><ol><li><code>dd</code> 刪除光標所在的整行內容，可以在 <code>dd</code> 前增加數字，比如 <code>2dd</code> 可以刪除從光標所在行開始的兩行</li><li><code>d$</code> 刪除從光標所在位置直到行尾</li><li><code>d^</code> 刪除從光標所在位置直到行首</li><li><code>dw</code> 刪除從光標所在位置直到下一個詞開始的所有內容</li></ol><h3 id="複製與黏貼" tabindex="-1">複製與黏貼 <a class="header-anchor" href="#複製與黏貼" aria-label="Permalink to “複製與黏貼”">​</a></h3><ol><li><code>yy</code> 複製當前行，在 <code>yy</code> 前添加數字可以複製多行</li><li><code>p</code> 在光標之後粘貼複製行</li><li><code>P</code> 在光標之前粘貼複製行</li></ol><p>上述就是可以在 VI/VIM 編輯器上使用的一些基本命令。在未來的教程中還會繼續教授一些更高級的命令。如果有任何疑問和建議，請在下方評論區留言。</p><hr>',30)),d("p",null,[e[1]||(e[1]=i("via: ",-1)),o(l,{href:"http://linuxtechlab.com/working-vi-editor-basics/"},{default:a(()=>[...e[0]||(e[0]=[i("http://linuxtechlab.com/working-vi-editor-basics/",-1)])]),_:1})]),d("p",null,[e[5]||(e[5]=i("作者：",-1)),o(l,{href:"http://linuxtechlab.com/author/shsuain/"},{default:a(()=>[...e[2]||(e[2]=[i("Shusain",-1)])]),_:1}),e[6]||(e[6]=i(" 譯者：",-1)),o(l,{href:"https://github.com/ljgibbslf"},{default:a(()=>[...e[3]||(e[3]=[i("ljgibbslf",-1)])]),_:1}),e[7]||(e[7]=i(" 校對：",-1)),o(l,{href:"https://github.com/wxy"},{default:a(()=>[...e[4]||(e[4]=[i("wxy",-1)])]),_:1})]),e[9]||(e[9]=d("p",null,"本文由 LCTT 原創編譯，Linux中國 榮譽推出",-1))])}const g=t(p,[["render",h]]);export{T as __pageData,g as default};
